const marketplaceCardBase=card,marketplaceDetailBase=detail,marketplaceCheckoutBase=checkout,marketplaceRenderBase=render;
header=function(){return `<div class="topbar">NASHIK–TRIMBAKESHWAR 2027 <span> • </span> Your stay for every sacred journey <a href="#/guide">Plan your visit ↗</a></div><header><div class="container nav">${brand}<nav class="desktop-main"><a href="#/stays">Find stays</a><a href="#/guide">Kumbh guide</a><a href="#/group-stays">Group bookings</a></nav><div class="header-actions"><span class="currency">INR ₹</span><a class="host-link" href="#/list-property">List your property</a><a class="trips-link" href="#/account" aria-label="Saved stays and trips">♡ <span>My trips</span></a><button class="btn small" onclick="login()">Login / Sign up</button><button class="mobile-toggle" aria-label="Toggle navigation" onclick="document.querySelector('.links').classList.toggle('open')">☰</button></div><nav class="links mobile-links"><a href="#/stays">Find stays</a><a href="#/guide">Kumbh guide</a><a href="#/list-property">List your property</a><a href="#/account">Saved stays & trips</a><a href="#/support">Help & group bookings</a></nav></div></header>`};
function categoryRail(){return `<div class="category-rail" role="group" aria-label="Browse accommodation"><button class="${state.type==='All stays'?'active':''}" onclick="categorySearch('All stays')"><span>▦</span>All stays</button>${categories.map((c,i)=>`<button class="${state.type===c?'active':''}" onclick="categorySearch('${c}')"><span>${['▤','♧','⌂','◇','△'][i]}</span>${['Hotels','Resorts','Homestays','Dharamshalas','Tent cities'][i]}</button>`).join('')}<a href="#/support"><span>♧</span>Group stays</a></div>`}
function listingSection(title,subtitle,list,filters={},empty='No stays are listed in this collection yet.'){return `<section class="market-section container"><div class="market-heading"><div><h2>${title}</h2><p>${subtitle}</p></div><a href="${escapeHtml(staysHref({...searchDefaults,...filters}))}">Browse stays →</a></div><div class="properties market-cards">${list.length?list.map(card).join(''):`<p class="notice">${empty}</p>`}</div></section>`}
home=function(){return `<section class="booking-hero"><div class="container"><div class="hero-split"><div><div class="event-chip"><span></span> Nashik & Trimbakeshwar · Kumbh 2027</div><h1>A meaningful journey.<br><em>A comfortable stay.</em></h1><p>Hotels, homestays and pilgrim stays.<br>One place to find your home in Nashik.</p><div class="hero-proof"><span>⌾ 5 local areas</span><span>♡ Stays for every budget</span></div></div><div class="destination-visual"><img src="${images.river}" alt="Historical photograph of pilgrims at Ramkund, Nashik"><div><span>DISCOVER NASHIK</span><strong>Stay close to the sacred.</strong><a href="#/guide">Explore Ramkund & the Godavari ↗</a></div></div></div><div class="booking-search"><div class="search-top"><strong>Find your stay</strong><span>Hotels · Homestays · Dharamshalas · Tent cities</span></div>${searchForm()}<div class="search-assist"><span>Popular:</span>${['Nashik City','Trimbakeshwar','Panchavati / Ramkund'].map(l=>`<button onclick="locationSearch('${l}')">${l==='Panchavati / Ramkund'?'Near Ramkund':l}</button>`).join('')}<a href="#/support">Booking for a group? →</a></div></div></div></section><div class="container">${categoryRail()}</div>${listingSection('Featured verified stays','Stays with confirmed verification.',properties.filter(p=>p.verified===true).slice(0,4),{verified:true},'No verified stays are listed yet.')}
${listingSection('Find your place in Nashik','Explore illustrative listings for your Kumbh journey.',properties.slice(0,4))}<section class="container market-section"><div class="planning-banner"><div><span class="eyebrow">A little planning goes a long way</span><h2>More people. More memories.<br>Find a stay that fits everyone.</h2><p>Travelling with family or a pilgrim group? Tell us what you need.</p><a class="btn" href="#/group-stays">Enquire about bulk accommodation →</a></div><img src="${photo(images.home)}" alt="AI illustration of a Maharashtrian courtyard homestay"></div></section><section class="container market-section"><div class="market-heading"><div><h2>Where would you like to stay?</h2><p>Pick the neighbourhood that works for your journey.</p></div></div><div class="destination-grid">${locations.slice(0,4).map((l,i)=>`<button onclick="locationSearch('${l}')"><img src="${photo([images.river,images.temple,images.river,images.hotel][i])}" alt="${i===3?'Illustrative accommodation near Nashik Road':l}"><strong>${l==='Panchavati / Ramkund'?'Panchavati & Ramkund':l}</strong><span>${['City stays & everyday convenience','Temple town & peaceful surroundings','Godavari ghats & old-city character','A convenient arrival base'][i]}</span></button>`).join('')}</div></section>${listingSection('Comfort that fits your budget','Simple, welcoming places with clearly presented prices.',properties.filter(p=>p.price<=2400).slice(0,4),{max:2400})}
${listingSection('Premium hotels and resorts','Explore premium accommodation around Nashik.',properties.filter(p=>p.type==='Premium Hotels & Resorts'),{type:'Premium Hotels & Resorts'})}
${listingSection('Stays near religious landmarks','Explore stays within 5 km of Ramkund or Trimbakeshwar Temple using illustrative distances.',properties.filter(p=>p.distance<=5).sort((a,b)=>a.distance-b.distance).slice(0,4),{distance:5})}
${listingSection('Accommodation within 15–50 km','Explore stays farther from the pilgrimage landmarks.',properties.filter(p=>p.distance>=15&&p.distance<=50),{minDistance:15,distance:50})}<section class="container market-section"><div class="market-heading"><div><h2>Your journey, your way</h2><p>Browse by the kind of stay you have in mind.</p></div></div><div class="intent-grid">${[['Family rooms','Space for everyone','family'],['Near the ghats','A base close to Ramkund','ghats'],['Quiet retreats','Rest after a full day','retreat'],['Under ₹2,000','Comfort within your budget','budget']].map(([t,d,k])=>`<button onclick="openCollection('${k}')"><strong>${t}</strong><span>${d}</span><b>↗</b></button>`).join('')}</div></section><section class="service-strip"><div class="container"><div><span>◇</span><strong>Know before you book</strong><p>Room capacity, house rules and sample cancellation terms.</p></div><div><span>₹</span><strong>A clear price breakdown</strong><p>Review room charges and illustrative taxes before checkout.</p></div><div><span>♡</span><strong>Designed for your journey</strong><p>Families, groups and different budgets in one place.</p></div></div></section><section class="container market-section"><div class="market-heading"><div><h2>Kumbh visitor information</h2><p>Plan your visit to Nashik and Trimbakeshwar.</p></div><a href="#/guide">Read the visitor guide &rarr;</a></div></section>${faqSection()}<section class="container market-section"><div class="host-banner"><div><span class="eyebrow">For property partners</span><h2>Have a place in Nashik?<br>Make room for a new journey.</h2><p>Introduce your hotel, homestay or pilgrim accommodation.</p></div><div class="host-actions"><a class="btn" href="#/list-property">List your property →</a><button class="btn outline" onclick="go('/rental-host')">Build your rental stay &rarr;</button></div></div></section>`};
card=function(p){
    const selectedLandmark=location.hash.split('?')[0]==='#/stays'?state.landmark:'';
    const landmark=selectedLandmark||p.landmark||(p.demo===false?'nearest landmark':listingLandmark(p));
    const distance=Object.hasOwn(p,'distanceKm')?p.distanceKm:(landmark===listingLandmark(p)&&Number.isFinite(p.distance)?p.distance:null);
    const liveParams=new URLSearchParams({checkin:state.checkin,checkout:state.checkout,guests:state.guests,rooms:state.rooms});
    const details=p.demo===false?sitePath(propertyPath(p.id,p.name),activeLocale)+'?'+liveParams:'#/stay/'+p.id;
    return `<article class="property booking-card">
        <div class="photo"><a href="${details}" aria-label="View ${escapeHtml(p.name)}">${p.image?`<img src="${escapeHtml(photo(p.image))}" ${pictureVariants(photo(p.image))} alt="${p.demo===false?'Photo of':'Illustrative accommodation for'} ${escapeHtml(p.name)}" loading="lazy">`:'<span class="stay-card-no-photo">Photo unavailable</span>'}</a>
            <span class="pill">${escapeHtml(p.type)}</span>
            ${p.demo===false?'':`<button class="heart ${saved.includes(p.id)?'saved':''}" aria-label="${saved.includes(p.id)?'Unsave':'Save'} ${escapeHtml(p.name)}" onclick="save(${p.id},this)">${saved.includes(p.id)?'&hearts;':'&#9825;'}</button>`}
            ${p.demo===false?'':'<span class="photo-caption">AI illustration</span>'}
        </div>
        <div class="property-body">
            <div class="card-title-row"><h3><a href="${details}">${escapeHtml(p.name)}</a></h3>${p.verified===true?'<span class="status">Verified</span>':''}</div>
            <p class="card-location">${escapeHtml(p.location)}</p>
            <p class="card-distance">${distance===null?`Distance to ${escapeHtml(landmark)} unavailable`:`${distance} km to ${escapeHtml(landmark)}${p.demo===false?'':' &middot; Illustrative'}`}</p>
            ${p.reviewCount?`<p class="card-distance">? ${p.rating.toFixed(1)} ? ${p.reviewCount} reviews</p>`:''}<p class="card-capacity">Up to ${p.capacity} guests per room</p>
            <div class="card-amenities">${p.amenities.map(a=>`<span>${escapeHtml(a==='Air conditioning'?'AC':a)}</span>`).join('')}</div>
            <div class="price-row"><div><strong>${money(p.nightlyPrice??p.price)}</strong><span> / night</span><small>${p.nightlyPrice!=null?'Average nightly rate, before taxes':p.demo===false?'Base rate, before taxes':'Illustrative rate'}</small>${p.stayPrice!=null?`<small>${money(p.stayPrice)} for your stay, before taxes</small>`:''}</div><a class="btn small" href="${details}">View details &rarr;</a></div>
        </div>
    </article>`;
};
detail=function(id){let html=marketplaceDetailBase(id);if(!selected)return html;html=html.replace('<div class="gallery-toolbar">','<nav class="property-nav"><a href="#property-overview">Overview</a><a href="#property-rooms" onclick="event.preventDefault();document.getElementById(\'property-rooms\').scrollIntoView({behavior:\'smooth\'})">Rooms</a><button onclick="document.querySelector(\'.map-panel\').scrollIntoView({behavior:\'smooth\'})">Location</button><button onclick="document.querySelector(\'.accessibility-note\').scrollIntoView({behavior:\'smooth\'})">Policies & access</button></nav><div class="gallery-toolbar">');html=html.replace('<h2>A restful pause in your journey.</h2>','<h2 id="property-overview">A restful pause in your journey.</h2>');html=html.replace('<h2 class="mt">A restful pause in your journey.</h2>','<h2 class="mt" id="property-overview">A restful pause in your journey.</h2>');html=html.replace('<h2>Choose your room</h2>','<h2 id="property-rooms">Choose your room</h2><p class="notice">Compare your room, capacity and price before continuing.</p>');html=html.replace('<span class="price">',`<div class="reserve-label">YOUR STAY SUMMARY</div><span class="price">`);html=html.replace('<p class="notice center mt">You won\'t be charged.','<div class="reservation-assurance">✓ Review all charges before demo payment<br>✓ Sample cancellation terms available</div><p class="notice center mt">You won\'t be charged.');return html};
checkout=function(stage){let html=marketplaceCheckoutBase(stage);if(!['review','payment'].includes(stage)){html=html.replace('<div class="form-field full"><label for="guest-note">',`<div class="form-field"><label for="guest-country">Country / region</label><select class="input" id="guest-country" name="country"><option>India</option><option>Other</option></select></div><div class="form-field"><label for="guest-arrival">Expected arrival (optional)</label><select class="input" id="guest-arrival" name="arrival"><option>Not sure yet</option><option>2 PM–6 PM</option><option>6 PM–10 PM</option><option>After 10 PM — request confirmation</option></select></div><div class="form-field full"><label for="guest-note">`);html=html.replace('<h2>Who\'s joining the journey?</h2>','<h2>Enter traveller details</h2><div class="checkout-guidance">Keep a government-issued photo ID handy for check-in. Enter sample details in this preview.</div>')}return html};
render=function(){marketplaceRenderBase();document.body.classList.toggle('market-home',!location.hash||location.hash==='#/');document.body.classList.toggle('market-results',location.hash.split('?')[0]==='#/stays');document.querySelectorAll('a[href="#property-overview"]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById('property-overview')?.scrollIntoView({behavior:'smooth'})});};



